// Canonical saint catalog and localization data, organized for access by faith.
// The neighboring data modules are compatibility re-exports.

import { CATHOLIC_SAINTS_CALENDAR, getCatholicSaintsForDate, getCatholicSaintForDate } from './catholic-saints.js';
import { SYNC_BOOK_TITLES, VERSION_BY_LANG } from './bible-books-i18n.js';
export { CATHOLIC_SAINTS_CALENDAR, getCatholicSaintsForDate, getCatholicSaintForDate };

export const BIBLE_BOOKS_I18N = Object.fromEntries(
  Object.entries(SYNC_BOOK_TITLES[VERSION_BY_LANG.en]).map(([bookId, englishTitle]) => [
    englishTitle,
    Object.fromEntries(
      Object.entries(VERSION_BY_LANG).map(([lang, version]) => [
        lang,
        SYNC_BOOK_TITLES[version]?.[bookId] || englishTitle
      ])
    )
  ])
);


