for (const collection of [DAILY_SAINTS_CALENDAR, TRADITION_FALLBACK_PATRONS]) {
  for (const entries of Object.values(collection)) {
    for (const event of entries) {
      const localizedNames = DAILY_SAINT_NAME_LOCALIZATIONS[event.name];
      if (!localizedNames) continue;
      for (const [index, language] of ["es", "fr", "de", "pt", "ru"].entries()) {
        if (!event[`name_${language}`]) {
          event[`name_${language}`] = localizedNames[index];
        }
      }
    }
  }
}

function matchesTradition(s, normConf) {
  const trads = s.traditions;

  if (normConf === 'catholic') {
    if (trads) {
      if (trads.includes('catholic') || trads.includes('all') || trads.includes('universal') || trads.includes('ecumenical')) return true;
      if (trads.includes('protestant') && !trads.includes('catholic')) return false;
      if (trads.includes('orthodox') && !trads.includes('catholic')) return false;
    }
    return true; // General Roman Calendar entries
  }

  if (normConf === 'traditional') {
    if (trads) {
      if (trads.includes('traditional') || trads.includes('catholic') || trads.includes('all') || trads.includes('universal')) return true;
      if (trads.includes('protestant') && !trads.includes('traditional')) return false;
    }
    return true;
  }

  if (normConf === 'orthodox' || normConf === 'eastern') {
    if (trads) {
      return trads.includes('orthodox') || trads.includes('eastern') || trads.includes('all') || trads.includes('universal');
    }
    const text = `${s.name || ''} ${s.title || ''}`.toLowerCase();
    if (/pope|papa|curé of ars|padre pio|thérèse|ignatius of loyola|francis xavier|dominic|thomas aquinas|alphonsus/i.test(text)) {
      return false;
    }
    return true;
  }

  if (normConf === 'protestant') {
    if (trads) {
      if (trads.includes('protestant')) return true;
      if (trads.includes('catholic') || trads.includes('orthodox') || trads.includes('traditional')) {
        return false;
      }
    }
    const name = (s.name || '').toLowerCase();
    const title = (s.title || '').toLowerCase();
    const bio = (s.bio || '').toLowerCase();
    const full = `${name} ${title} ${bio}`;

    // Negative filter: Roman Catholic papacy, dogmas, counter-reformation orders & apparitions
    if (
      /pope|papa|pontiff|bishop of rome|jesuit|carmelite|salesian|capuchin|apparition|apparizione|lourdes|fatima|fátima|guadalupe|pilar|rosary|rosario|immaculate conception|assumption of the b\.v\.m|assunzione|our lady of|madonna|mater dolorosa|sorrows|purgatory|all souls|st\. thomas aquinas|st\. francis of assisi|st\. anthony of padua|st\. dominic|st\. clare|st\. catherine of siena|st\. teresa of avila|st\. john of the cross|st\. ignatius of loyola|st\. francis xavier|st\. charles borromeo|st\. philip neri|st\. vincent de paul|st\. john vianney|st\. thérèse|padre pio|pio of pietrelcina|maximilian kolbe|maria goretti|josemaría|stanislaus|alphonsus/i.test(
        full
      )
    ) {
      return false;
    }

    // Positive filter: Biblical apostles/evangelists/feasts of Christ & pre-schism Church Fathers / Reformers
    if (
      /apostle|evangelist|nativity|christmas|epiphany|annunciation|transfiguration|visitation|innocents|presentation|baptist|stephen|magdalene|timothy|titus|barnabas|athanasius|basil|chrysostom|ambrose|jerome|augustine|irenaeus|justin martyr|polycarp|ignatius of antioch|cyprian|patrick|columba|boniface|bede|luther|calvin|bonhoeffer|lewis|tyndale|cranmer|wesley|hus/i.test(
        full
      )
    ) {
      return true;
    }

    return false;
  }

  return true; // ecumenical
}

function deduplicateExactSaints(list) {
  const result = [];
  for (const item of list) {
    const isDup = result.some(r => {
      if (r.name && item.name && r.name.trim().toLowerCase() === item.name.trim().toLowerCase()) return true;
      if (r.name_it && item.name_it && r.name_it.trim().toLowerCase() === item.name_it.trim().toLowerCase()) return true;
      return false;
    });
    if (!isDup) {
      result.push(item);
    }
  }
  return result;
}
export function getSaintsForDate(date, confession = 'ecumenical', userNationality = 'universal', lang = 'it') {
  if (!date) date = new Date();
  const m = date.getMonth() + 1;
  const d = date.getDate();
  const key = `${m}-${d}`;
  const normConf = (confession || 'ecumenical').toLowerCase();
  const normNat = (userNationality || 'universal').toLowerCase();

  // 1. Strict Eastern Orthodox / Byzantine Synaxarion resolution
  if (normConf === 'orthodox' || normConf === 'eastern') {
    const orth = getOrthodoxSaintsForDate(date, normNat, lang);
    if (orth && orth.length > 0) {
      return orth.map(s => ({
        ...s,
        dateStr: `${m}/${d}`,
        colorMeta: s.colorMeta || getLiturgicalColorMeta(s, lang, normConf, normNat),
        nationalityMeta: s.nationalityMeta || getNationalityMeta(s.nationality, lang)
      }));
    }
  }

  // 2. Strict Catholic / Traditional Roman Rite resolution
  if (normConf === 'catholic' || normConf === 'traditional') {
    const cathList = getCatholicSaintsForDate(date, lang);
    if (cathList && cathList.length > 0) {
      const results = [];
      if (normNat && normNat !== 'universal') {
        const curatedNat = (NATIONAL_SAINTS_BY_DATE[normNat]?.[key] || []).filter(ns => matchesTradition(ns, normConf));
        for (const ns of curatedNat) {
          results.push({
            ...ns,
            nationality: normNat,
            dateStr: `${m}/${d}`,
            colorMeta: getLiturgicalColorMeta(ns, lang, normConf, normNat),
            nationalityMeta: getNationalityMeta(normNat, lang)
          });
        }
      }

      for (const cs of cathList) {
        const exists = results.some(r =>
          (r.name && cs.name && r.name.trim().toLowerCase() === cs.name.trim().toLowerCase()) ||
          (r.name_it && cs.name_it && r.name_it.trim().toLowerCase() === cs.name_it.trim().toLowerCase())
        );
        if (!exists) {
          const trueNat = cs.nat || inferSaintNationality(cs, key);
          const finalNat = (normNat && normNat !== 'universal' && trueNat === normNat) ? normNat : (trueNat || 'universal');
          results.push({
            ...cs,
            nationality: finalNat,
            dateStr: `${m}/${d}`,
            colorMeta: getLiturgicalColorMeta(cs, lang, normConf, normNat),
            nationalityMeta: getNationalityMeta(finalNat, lang)
          });
        }
      }

      if (results.length > 0) {
        return results;
      }
    }
  }

  const dayFeasts = DAILY_SAINTS_CALENDAR[key] || [];
  const matchedGeneral = dayFeasts.filter(s => matchesTradition(s, normConf));

  // 3. CASE A: Universal Calendar — show the international mosaic of saints for normConf
  if (!normNat || normNat === 'universal') {
    const universalResults = matchedGeneral.map(s => {
      const trueNat = inferSaintNationality(s, key);
      return {
        ...s,
        nationality: trueNat,
        dateStr: `${m}/${d}`,
        colorMeta: getLiturgicalColorMeta(s, lang, normConf, normNat),
        nationalityMeta: getNationalityMeta(trueNat, lang)
      };
    });

    // Include curated national feasts matching this tradition in the universal mix
    for (const [natCode, byDate] of Object.entries(NATIONAL_SAINTS_BY_DATE)) {
      const natList = (byDate[key] || []).filter(ns => matchesTradition(ns, normConf));
      for (const ns of natList) {
        const exists = universalResults.some(
          u => (u.name && ns.name && u.name === ns.name) || (u.name_it && ns.name_it && u.name_it === ns.name_it)
        );
        if (!exists) {
          universalResults.push({
            ...ns,
            nationality: ns.nationality || natCode,
            dateStr: `${m}/${d}`,
            colorMeta: getLiturgicalColorMeta(ns, lang, normConf, normNat),
            nationalityMeta: getNationalityMeta(ns.nationality || natCode, lang)
          });
        }
      }
    }

    if (universalResults.length > 0) {
      return deduplicateExactSaints(universalResults);
    }

    // If no Western entry matched
    if (normConf === 'catholic' || normConf === 'traditional' || normNat === 'it') {
      const cathList = getCatholicSaintsForDate(date, lang);
      if (cathList && cathList.length > 0) {
        return cathList.map(cath => ({
          ...cath,
          nationality: cath.nationality || 'universal',
          dateStr: `${m}/${d}`,
          colorMeta: getLiturgicalColorMeta(cath, lang, normConf, normNat),
          nationalityMeta: getNationalityMeta(cath.nationality || 'universal', lang)
        }));
      }
    } else if (normConf !== 'protestant') {
      const orthUniv = getOrthodoxSaintsForDate(date, 'universal', lang);
      if (orthUniv && orthUniv.length > 0) {
        return orthUniv.map(s => ({
          ...s,
          dateStr: `${m}/${d}`,
          colorMeta: getLiturgicalColorMeta(s, lang, normConf, normNat),
          nationalityMeta: s.nationalityMeta || getNationalityMeta(s.nationality, lang)
        }));
      }
    }
  } else {
    // 4. CASE B: Specific Nationality Selected (it, ro, gr, ru, ge, rs, es, fr, de, en, pt)
    const nationalList = [];

    // 4a. Curated national saints for (normNat, key) matching normConf
    const curatedNat = (NATIONAL_SAINTS_BY_DATE[normNat]?.[key] || []).filter(ns => matchesTradition(ns, normConf));
    for (const ns of curatedNat) {
      nationalList.push({
        ...ns,
        nationality: normNat,
        dateStr: `${m}/${d}`,
        colorMeta: getLiturgicalColorMeta(ns, lang, normConf, normNat),
        nationalityMeta: getNationalityMeta(normNat, lang)
      });
    }

    // 4b. If user selected an Eastern nationality in ecumenical mode, check Orthodox calendar
    if (['ro', 'gr', 'ru', 'ge', 'rs'].includes(normNat) && normConf !== 'protestant') {
      const orthNat = getOrthodoxSaintsForDate(date, normNat, lang).filter(os => os.nationality === normNat);
      for (const os of orthNat) {
        const exists = nationalList.some(
          n => (n.name && os.name && n.name === os.name) || (n.name_ro && os.name_ro && n.name_ro === os.name_ro)
        );
        if (!exists) {
          nationalList.push({
            ...os,
            nationality: normNat,
            dateStr: `${m}/${d}`,
            colorMeta: getLiturgicalColorMeta(os, lang, normConf, normNat),
            nationalityMeta: getNationalityMeta(normNat, lang)
          });
        }
      }
    }

    // 4c. Inspect general calendar entries matching normConf
    const exactNatGeneral = [];
    const universalGeneral = [];
    const generalCalendarOther = [];

    for (const s of matchedGeneral) {
      const trueNat = inferSaintNationality(s, key);
      if (trueNat === normNat) {
        exactNatGeneral.push({
          ...s,
          nationality: normNat,
          dateStr: `${m}/${d}`,
          colorMeta: getLiturgicalColorMeta(s, lang, normConf, normNat),
          nationalityMeta: getNationalityMeta(normNat, lang)
        });
      } else if (trueNat === 'universal') {
        universalGeneral.push({
          ...s,
          nationality: 'universal',
          dateStr: `${m}/${d}`,
          colorMeta: getLiturgicalColorMeta(s, lang, normConf, normNat),
          nationalityMeta: getNationalityMeta('universal', lang)
        });
      } else {
        generalCalendarOther.push({
          ...s,
          nationality: 'universal',
          dateStr: `${m}/${d}`,
          colorMeta: getLiturgicalColorMeta(s, lang, normConf, normNat),
          nationalityMeta: getNationalityMeta('universal', lang)
        });
      }
    }

    for (const item of [...exactNatGeneral, ...universalGeneral]) {
      const exists = nationalList.some(
        n => (n.name && item.name && n.name === item.name) || (n.name_it && item.name_it && n.name_it === item.name_it)
      );
      if (!exists) {
        nationalList.push(item);
      }
    }

    if (nationalList.length === 0 && generalCalendarOther.length > 0) {
      nationalList.push(...generalCalendarOther);
    }

    // If still empty, fallbacks
    if (nationalList.length === 0) {
      if (normConf === 'catholic' || normConf === 'traditional' || normNat === 'it') {
        const cathFallback = getCatholicSaintsForDate(date, lang);
        if (cathFallback && cathFallback.length > 0) {
          return cathFallback.map(c => ({
            ...c,
            nationality: c.nationality || normNat,
            dateStr: `${m}/${d}`,
            colorMeta: getLiturgicalColorMeta(c, lang, normConf, normNat),
            nationalityMeta: getNationalityMeta(c.nationality || normNat, lang)
          }));
        }
      } else if (normConf !== 'protestant') {
        const orthNatFallback = getOrthodoxSaintsForDate(date, normNat, lang);
        if (orthNatFallback && orthNatFallback.length > 0) {
          return orthNatFallback.map(s => ({
            ...s,
            dateStr: `${m}/${d}`,
            colorMeta: getLiturgicalColorMeta(s, lang, normConf, normNat),
            nationalityMeta: s.nationalityMeta || getNationalityMeta(s.nationality, lang)
          }));
        }
      }
    }

    if (nationalList.length > 0) {
      nationalList.sort((a, b) => {
        const aM = a.nationality === normNat ? 1 : 0;
        const bM = b.nationality === normNat ? 1 : 0;
        if (aM !== bM) return bM - aM;
        if (a.color === 'red' && b.color !== 'red') return -1;
        if (b.color === 'red' && a.color !== 'red') return 1;
        return 0;
      });
      return deduplicateExactSaints(nationalList);
    }
  }

  // 4. Fallback tradition-specific patron for ordinary ferias
  const fallbackList = TRADITION_FALLBACK_PATRONS[normConf] || TRADITION_FALLBACK_PATRONS.ecumenical;
  const fallbackIndex = (m * 31 + d) % fallbackList.length;
  const patron = fallbackList[fallbackIndex];
  const patTrueNat = inferSaintNationality(patron, key);
  const patFinalNat = (!normNat || normNat === 'universal')
    ? patTrueNat
    : (patTrueNat === normNat ? normNat : 'universal');

  return [
    {
      ...patron,
      nationality: patFinalNat,
      dateStr: `${m}/${d}`,
      bio: patron.bio || 'Commemoration of holy fathers and faithful witnesses who dedicated their lives to constant unceasing prayer in Christ.',
      colorMeta: getLiturgicalColorMeta(patron, lang, normConf, normNat),
      nationalityMeta: getNationalityMeta(patFinalNat, lang)
    }
  ];
}

export function getTodaySaints(confession = 'ecumenical', userNationality = 'universal', lang = 'it') {
  return getSaintsForDate(new Date(), confession, userNationality, lang);
}

