export function resolveSaintLiturgicalMeta(saint, confession = 'ecumenical', userNationality = 'universal', lang = 'it') {
  if (!saint) {
    const w = LITURGICAL_COLORS.white;
    return { ...w, displayName: w[`name_${lang}`] || w.name_it || w.name, symbol: '' };
  }

  if (typeof saint === 'string') {
    saint = { color: saint };
  }

  const normConf = (confession || 'ecumenical').toLowerCase();
  const normNat = (userNationality || 'universal').toLowerCase();

  const isRomanian = normNat === 'ro' || (normConf === 'orthodox' && normNat === 'ro');
  const isGreek = normNat === 'gr' || (normConf === 'orthodox' && normNat === 'gr');
  const isSlavic = ['ru', 'rs', 'ge'].includes(normNat) || (normConf === 'orthodox' && ['ru', 'rs', 'ge'].includes(normNat));
  const isOrthodox = normConf === 'orthodox' || normConf === 'eastern';
  const isCatholic = normConf === 'catholic' || normConf === 'traditional' || (!isOrthodox && normConf !== 'protestant' && ['it', 'es', 'fr', 'de', 'pt', 'en', 'universal'].includes(normNat));
  const isProtestant = normConf === 'protestant';

  const rawColor = (saint.color || 'white').toLowerCase();
  const rawRank = (saint.rank || 'memorial').toLowerCase();
  const rawNat = (saint.nationality || '').toLowerCase();
  const sName = (saint.name || '') + ' ' + (saint.name_it || '') + ' ' + (saint.name_ro || '') + ' ' + (saint.name_la || '');
  const sTitle = (saint.title || '') + ' ' + (saint.title_it || '') + ' ' + (saint.title_ro || '');
  const combinedText = (sName + ' ' + sTitle).toLowerCase();

  const isSolemnity = rawRank === 'solemnity';

  // True martyrs, apostles and cross commemorations
  const isMartyrOrApostle = rawColor === 'red' || /(martyr|martire|mucenic|m\u00e1rtir|m\u00e4rtyrer|apostle|apostolo|apostol|ap\u00f3stol|evangelist|evangelista|battista martirio|martyrdom|esaltazione della croce|exaltation of the holy cross|in\u0103l\u021barea sfintei cruci)/i.test(combinedText);

  // Romanian Synodal Saints
  const isRomanianSaint = rawNat === 'ro' || /(parascheva|dimitrie cel nou|basarabov|ioan cel nou|filofteia|stefan cel mare|\u0219tefan cel mare|calinic|antim|andrei \u0219aguna|andrei saguna|varlaam|dosoftei|teodora de la sihla|gheorghe de la cernica|paisie de la neamt|visarion|oprea|sofronie|iacob putneanul|brancoveanu|br\u00e2ncoveanu)/i.test(combinedText);

  let finalColorKey = 'white';
  let symbol = '';
  let customName = null;
  let traditionSystem = 'catholic';

  if (isRomanian) {
    traditionSystem = 'romanian_orthodox';
    // Romanian Synodal Typikon (BOR):
    // 1. Cruce Roșie (†): Praznice Împărătești and great feasts of precept
    if (isSolemnity || /(lord|signore|domnului|easter|pascha|pa\u0219ti|christmas|cr\u0103ciun|theophany|epifania|boboteaza|assumption|adormirea|ascension|\u00een\u0103l\u021barea|pentecost|rusalii|transfiguration|schimbarea la fa\u021b\u0103|cross|crucii|buna vestire|annunciation|taierea imprejur|t\u0103ierea \u00eemprejur)/i.test(combinedText)) {
      finalColorKey = 'red';
      symbol = '†';
      customName = CROSS_LABELS_I18N.red_cross[lang] || CROSS_LABELS_I18N.red_cross.en;
    } else if (isRomanianSaint || rawColor === 'blue') {
      // 2. Cruce Albastră (†): Romanian Saints approved by the Holy Synod
      finalColorKey = 'blue';
      symbol = '†';
      customName = CROSS_LABELS_I18N.blue_cross[lang] || CROSS_LABELS_I18N.blue_cross.en;
    } else if (rawRank === 'feast' || rawColor === 'black') {
      // 3. Cruce Neagră (†): Saints with Polyeleos / Great Doxology (without precept - work permitted)
      finalColorKey = 'black';
      symbol = '†';
      customName = CROSS_LABELS_I18N.black_cross[lang] || CROSS_LABELS_I18N.black_cross.en;
    } else {
      // 4. Fără cruce: Simple commemorations / daily ferias
      finalColorKey = 'white';
      symbol = '';
      customName = CROSS_LABELS_I18N.no_cross[lang] || CROSS_LABELS_I18N.no_cross.en;
    }
  } else if (isGreek) {
    traditionSystem = 'greek_orthodox';
    if (isSolemnity || /(lord|theotokos|virgin|panagia|despotic|theometoric|apostle|evangelist|great-martyr|megalomartyr)/i.test(combinedText)) {
      finalColorKey = 'red';
      symbol = '†';
      customName = (lang === 'el' || lang === 'gr') ? 'Κόκκινος Σταυρός' : (CROSS_LABELS_I18N.red_cross[lang] || CROSS_LABELS_I18N.red_cross.en);
    } else if (rawRank === 'feast' || rawColor === 'black' || rawColor === 'blue') {
      finalColorKey = 'black';
      symbol = '†';
      customName = (lang === 'el' || lang === 'gr') ? 'Μαύρος Σταυρός' : (CROSS_LABELS_I18N.black_cross[lang] || CROSS_LABELS_I18N.black_cross.en);
    } else {
      finalColorKey = 'white';
      symbol = '';
      customName = (lang === 'el' || lang === 'gr') ? 'Χωρίς σταυρό' : (CROSS_LABELS_I18N.no_cross[lang] || CROSS_LABELS_I18N.no_cross.en);
    }
  } else if (isSlavic) {
    traditionSystem = 'slavic_orthodox';
    if (isSolemnity || /(lord|theotokos|bogoroditsa|blagoveshchenie|uspenskie|velikiy|apostle)/i.test(combinedText)) {
      finalColorKey = 'red';
      symbol = '†';
      customName = CROSS_LABELS_I18N.red_cross[lang] || CROSS_LABELS_I18N.red_cross.en;
    } else if (rawRank === 'feast' || rawColor === 'black' || rawColor === 'blue') {
      finalColorKey = 'black';
      symbol = '†';
      customName = CROSS_LABELS_I18N.black_cross[lang] || CROSS_LABELS_I18N.black_cross.en;
    } else {
      finalColorKey = 'white';
      symbol = '';
      customName = CROSS_LABELS_I18N.no_cross[lang] || CROSS_LABELS_I18N.no_cross.en;
    }
  } else if (isOrthodox) {
    traditionSystem = 'pan_orthodox';
    if (isSolemnity || rawColor === 'red') {
      finalColorKey = 'red';
      symbol = '†';
      customName = CROSS_LABELS_I18N.red_cross[lang] || CROSS_LABELS_I18N.red_cross.en;
    } else if (rawRank === 'feast' || rawColor === 'black' || rawColor === 'blue') {
      finalColorKey = 'black';
      symbol = '†';
      customName = CROSS_LABELS_I18N.black_cross[lang] || CROSS_LABELS_I18N.black_cross.en;
    } else {
      finalColorKey = 'white';
      symbol = '';
      customName = CROSS_LABELS_I18N.no_cross[lang] || CROSS_LABELS_I18N.no_cross.en;
    }
  } else if (isCatholic) {
    traditionSystem = 'catholic';
    // Roman Catholic (General Roman Calendar & CEI):
    // Authentic liturgical vestment colors only. NO calendar crosses.
    symbol = '';
    customName = null;

    if (rawColor === 'white') {
      finalColorKey = 'white';
    } else if (rawColor === 'red') {
      finalColorKey = 'red';
    } else if (rawColor === 'violet' || rawColor === 'purple') {
      finalColorKey = 'violet';
    } else if (rawColor === 'green') {
      finalColorKey = 'green';
    } else if (rawColor === 'rose') {
      finalColorKey = 'rose';
    } else if ((normNat === 'es' || normNat === 'pt') && /(immacul|inmacul|neprih\u0103nita)/i.test(combinedText)) {
      finalColorKey = 'blue';
    } else if (isMartyrOrApostle && !/(conversion|conversione|cattedra|chair of st\. peter|evangelista giovanni|john the apostle)/i.test(combinedText)) {
      finalColorKey = 'red';
    } else {
      finalColorKey = 'white';
    }
  } else if (isProtestant) {
    traditionSystem = 'protestant';
    symbol = '';
    customName = null;
    finalColorKey = isMartyrOrApostle ? 'red' : ((rawColor === 'violet' || rawColor === 'purple') ? 'violet' : 'white');
  }

  const baseMeta = LITURGICAL_COLORS[finalColorKey] || LITURGICAL_COLORS.white;
  const localizedColorName = (lang && baseMeta[`name_${lang}`]) || baseMeta.name_it || baseMeta.name;
  const displayName = customName || localizedColorName;

  return {
    ...baseMeta,
    id: finalColorKey,
    color: finalColorKey,
    name: displayName,
    displayName: displayName,
    colorName: localizedColorName,
    symbol: symbol,
    traditionSystem: traditionSystem
  };
}

export function getLiturgicalColorMeta(colorKeyOrSaint, lang = 'it', confession = 'ecumenical', userNationality = 'universal', saint = null) {
  if (colorKeyOrSaint && typeof colorKeyOrSaint === 'object') {
    return resolveSaintLiturgicalMeta(colorKeyOrSaint, confession, userNationality, lang);
  }
  if (saint && typeof saint === 'object') {
    return resolveSaintLiturgicalMeta(saint, confession, userNationality, lang);
  }
  const colorKey = typeof colorKeyOrSaint === 'string' ? colorKeyOrSaint : 'white';
  const normKey = LITURGICAL_COLORS[colorKey] ? colorKey : 'white';
  const meta = LITURGICAL_COLORS[normKey] || LITURGICAL_COLORS.white;
  const localizedName = (lang && meta[`name_${lang}`]) || meta.name_it || meta.name;
  return {
    ...meta,
    name: localizedName,
    displayName: localizedName
  };
}

