export function localizeScriptureRef(scriptureRef, lang = 'it') {
  if (!scriptureRef) return lang === 'it' ? 'Evangelo di Cristo' : (lang === 'la' ? 'Evangelium Christi' : 'Gospel of Christ');
  if (lang === 'en') return scriptureRef;

  let localized = scriptureRef;
  for (const [bookEn, trans] of Object.entries(BIBLE_BOOKS_I18N)) {
    if (localized.includes(bookEn)) {
      const replacement = trans[lang] || trans.it || bookEn;
      localized = localized.replace(bookEn, replacement);
      break;
    }
  }
  return localized;
}

export function getLocalizedColorName(colorKey, lang = 'it') {
  const norm = (colorKey === 'blue' || colorKey === 'red' || colorKey === 'black') ? colorKey : 'white';
  const col = COLORS_I18N[norm] || COLORS_I18N.white;
  return col[lang] || col.it || col.en;
}

export function getLocalizedRankName(rankKey, lang = 'it') {
  const rnk = RANKS_I18N[rankKey] || RANKS_I18N.memorial;
  return rnk[lang] || rnk.it || rnk.en;
}

export function translateSaintName(rawName, lang = 'it', fallbackName = '') {
  if (!rawName) return '';
  if (lang === 'en') return rawName;

  // Check exact catalog or mapping
  if (SAINTS_I18N_CATALOG[rawName] && SAINTS_I18N_CATALOG[rawName][lang] && SAINTS_I18N_CATALOG[rawName][lang].name) {
    return SAINTS_I18N_CATALOG[rawName][lang].name;
  }

  // Match known saint names
  for (const [key, mapping] of Object.entries(SAINT_NAMES_I18N)) {
    if (rawName.startsWith(key)) {
      let suffix = rawName.slice(key.length);
      for (const [pKey, pMap] of Object.entries(PLACE_SUFFIXES_I18N)) {
        if (suffix.includes(pKey)) {
          suffix = suffix.replace(pKey, pMap[lang] || pMap.it || pKey);
        }
      }
      return mapping[lang] ? mapping[lang] + suffix : rawName;
    }
  }

  if (fallbackName && (lang === 'it' || lang === 'la' || lang === 'ro')) {
    return fallbackName;
  }

  // For Romance languages (es, fr, pt) when fallbackName (Italian) is available, adapt it cleanly
  if (fallbackName && (lang === 'es' || lang === 'fr' || lang === 'pt')) {
    let rom = fallbackName;
    if (lang === 'es') {
      rom = rom
        .replace(/\bSant'/g, 'San ')
        .replace(/\bSanti\b/g, 'Santos')
        .replace(/\bSante\b/g, 'Santas')
        .replace(/\bVescovo\b/g, 'Obispo')
        .replace(/\bMartire\b/g, 'Mártir')
        .replace(/\bMartiri\b/g, 'Mártires')
        .replace(/\bVergine\b/g, 'Virgen')
        .replace(/\bApostolo\b/g, 'Apóstol')
        .replace(/\bApostoli\b/g, 'Apóstoles')
        .replace(/\bProfeta\b/g, 'Profeta')
        .replace(/\bConfessore\b/g, 'Confesor')
        .replace(/\s+e\s+/g, ' y ')
        .replace(/\s+di\s+/g, ' de ')
        .replace(/\s+da\s+/g, ' de ');
      return rom;
    }
    if (lang === 'fr') {
      rom = rom
        .replace(/\bSant'/g, 'Saint ')
        .replace(/\bSan\b/g, 'Saint')
        .replace(/\bSanto\b/g, 'Saint')
        .replace(/\bSanta\b/g, 'Sainte')
        .replace(/\bSanti\b/g, 'Saints')
        .replace(/\bVescovo\b/g, 'Évêque')
        .replace(/\bMartire\b/g, 'Martyr')
        .replace(/\bMartiri\b/g, 'Martyrs')
        .replace(/\bVergine\b/g, 'Vierge')
        .replace(/\bApostolo\b/g, 'Apôtre')
        .replace(/\bApostoli\b/g, 'Apôtres')
        .replace(/\bProfeta\b/g, 'Prophète')
        .replace(/\bConfessore\b/g, 'Confesseur')
        .replace(/\s+e\s+/g, ' et ')
        .replace(/\s+di\s+/g, ' de ')
        .replace(/\s+da\s+/g, ' de ');
      return rom;
    }
    if (lang === 'pt') {
      rom = rom
        .replace(/\bSant'/g, 'Santo ')
        .replace(/\bSan\b/g, 'São')
        .replace(/\bSanti\b/g, 'Santos')
        .replace(/\bVescovo\b/g, 'Bispo')
        .replace(/\bMartire\b/g, 'Mártir')
        .replace(/\bMartiri\b/g, 'Mártires')
        .replace(/\bVergine\b/g, 'Virgem')
        .replace(/\bApostolo\b/g, 'Apóstolo')
        .replace(/\bApostoli\b/g, 'Apóstolos')
        .replace(/\bConfessore\b/g, 'Confessor')
        .replace(/\s+di\s+/g, ' de ')
        .replace(/\s+da\s+/g, ' de ');
      return rom;
    }
  }

  // German & general prefix replacement
  let res = rawName;
  if (lang === 'de') {
    res = res
      .replace(/^Holy Great Martyr\s+/i, 'Hl. Großmärtyrer ')
      .replace(/^Holy Hieromartyr\s+/i, 'Hl. Hieromärtyrer ')
      .replace(/^Holy Virgin-Martyr\s+/i, 'Hl. Jungfrau und Märtyrerin ')
      .replace(/^Holy Martyrs\s+/i, 'Hll. Märtyrer ')
      .replace(/^Holy Martyr\s+/i, 'Hl. Märtyrer ')
      .replace(/^Holy Venerable\s+/i, 'Hl. Ehrwürdiger ')
      .replace(/^Holy Apostles\s+/i, 'Hll. Apostel ')
      .replace(/^Holy Apostle\s+/i, 'Hl. Apostel ')
      .replace(/^Holy Prophet\s+/i, 'Hl. Prophet ')
      .replace(/\bSt\.\s+/g, 'Hl. ')
      .replace(/\bSaints\s+/g, 'Hll. ')
      .replace(/\s+&\s+/g, ' und ')
      .replace(/\s+and\s+/g, ' und ')
      .replace(/\s+of\s+/g, ' von ');
    return res;
  }

  if (res.startsWith('St. ')) {
    const pref = PREFIXES_I18N['St.'][lang] || 'San';
    res = pref + ' ' + res.slice(4);
  } else if (res.startsWith('Saints ')) {
    const pref = PREFIXES_I18N['Saints'][lang] || 'Santi';
    res = pref + ' ' + res.slice(7);
  }

  return res;
}

export function translateSaintTitle(rawTitle, lang = 'it', fallbackTitle = '') {
  if (!rawTitle) return '';
  if (lang === 'en') return rawTitle;
  if (lang === 'it' && fallbackTitle) return fallbackTitle;

  if (fallbackTitle && (lang === 'es' || lang === 'fr' || lang === 'pt' || lang === 'la')) {
    let rom = fallbackTitle;
    if (lang === 'es') {
      return rom
        .replace(/\bVescovo\b/g, 'Obispo')
        .replace(/\bVescovi\b/g, 'Obispos')
        .replace(/\bMartire\b/g, 'Mártir')
        .replace(/\bMartiri\b/g, 'Mártires')
        .replace(/\bVergine\b/g, 'Virgen')
        .replace(/\bDottore della Chiesa\b/g, 'Doctor de la Iglesia')
        .replace(/\bApostolo\b/g, 'Apóstol')
        .replace(/\bApostoli\b/g, 'Apóstoles')
        .replace(/\bTaumaturgo\b/g, 'Taumaturgo')
        .replace(/\bAbate\b/g, 'Abad')
        .replace(/\bMonaco\b/g, 'Monje')
        .replace(/\bSacerdote\b/g, 'Sacerdote')
        .replace(/\s+e\s+/g, ' y ')
        .replace(/\s+di\s+/g, ' de ')
        .replace(/\s+della\s+/g, ' de la ')
        .replace(/\s+del\s+/g, ' del ');
    }
    if (lang === 'fr') {
      return rom
        .replace(/\bVescovo\b/g, 'Évêque')
        .replace(/\bVescovi\b/g, 'Évêques')
        .replace(/\bMartire\b/g, 'Martyr')
        .replace(/\bMartiri\b/g, 'Martyrs')
        .replace(/\bVergine\b/g, 'Vierge')
        .replace(/\bDottore della Chiesa\b/g, "Docteur de l'Église")
        .replace(/\bApostolo\b/g, 'Apôtre')
        .replace(/\bApostoli\b/g, 'Apôtres')
        .replace(/\bTaumaturgo\b/g, 'Thaumaturge')
        .replace(/\bAbate\b/g, 'Abbé')
        .replace(/\bMonaco\b/g, 'Moine')
        .replace(/\bSacerdote\b/g, 'Prêtre')
        .replace(/\s+e\s+/g, ' et ')
        .replace(/\s+di\s+/g, ' de ')
        .replace(/\s+della\s+/g, ' de la ')
        .replace(/\s+del\s+/g, ' du ');
    }
    if (lang === 'pt') {
      return rom
        .replace(/\bVescovo\b/g, 'Bispo')
        .replace(/\bVescovi\b/g, 'Bispos')
        .replace(/\bMartire\b/g, 'Mártir')
        .replace(/\bMartiri\b/g, 'Mártires')
        .replace(/\bVergine\b/g, 'Virgem')
        .replace(/\bDottore della Chiesa\b/g, 'Doutor da Igreja')
        .replace(/\bApostolo\b/g, 'Apóstolo')
        .replace(/\bApostoli\b/g, 'Apóstolos')
        .replace(/\bAbate\b/g, 'Abade')
        .replace(/\bMonaco\b/g, 'Monge')
        .replace(/\s+di\s+/g, ' de ')
        .replace(/\s+della\s+/g, ' da ')
        .replace(/\s+del\s+/g, ' do ');
    }
  }

  let trans = rawTitle;
  const tokens = [
    ['Great Martyr', { it: 'Grande Martire', es: 'Gran Mártir', fr: 'Grand Martyr', de: 'Großmärtyrer', pt: 'Grande Mártir', ro: 'Mare Mucenic', la: 'Magnus Martyr', ru: 'Великомученик' }],
    ['Hieromartyr', { it: 'Ieromartire', es: 'Hieromártir', fr: 'Hiéromartyr', de: 'Hieromärtyrer', pt: 'Hieromártir', ro: 'Sfințit Mucenic', la: 'Hieromartyr', ru: 'Священномученик' }],
    ['Venerable-Martyr', { it: 'Venerabile Martire', es: 'Venerable Mártir', fr: 'Vénérable Martyr', de: 'Ehrwürdiger Märtyrer', pt: 'Venerável Mártir', ro: 'Cuvios Mucenic', la: 'Venerabilis Martyr', ru: 'Преподобномученик' }],
    ['Equal-to-the-Apostles', { it: 'Eguale agli Apostoli', es: 'Igual a los Apóstoles', fr: 'Égal aux Apôtres', de: 'Apostelgleicher', pt: 'Igual aos Apóstolos', ro: 'Întocmai cu Apostolii', la: 'Aequalis Apostolis', ru: 'Равноапостольный' }],
    ['Unmercenary', { it: 'Anargiro (Gratuito)', es: 'Anárgiro', fr: 'Anargyre', de: 'Uneigennütziger Arzt', pt: 'Anárgiro', ro: 'Doctor fără de arginți', la: 'Anargyros', ru: 'Бессребреник' }],
    ['Wonderworker', { it: 'Taumaturgo', es: 'Taumaturgo', fr: 'Thaumaturge', de: 'Wundertäter', pt: 'Taumaturgo', ro: 'Făcător de minuni', la: 'Thaumaturgus', ru: 'Чудотворец' }],
    ['Confessor', { it: 'Confessore', es: 'Confesor', fr: 'Confesseur', de: 'Bekenner', pt: 'Confessor', ro: 'Mărturisitor', la: 'Confessor', ru: 'Исповедник' }],
    ['Prophet', { it: 'Profeta', es: 'Profeta', fr: 'Prophète', de: 'Prophet', pt: 'Profeta', ro: 'Proroc', la: 'Propheta', ru: 'Пророк' }],
    ['Protomartyr', { it: 'Protomartire', es: 'Protomártir', fr: 'Protomartyr', de: 'Erstmärtyrer', pt: 'Protomártir', ro: 'Întâiul Mucenic', la: 'Protomartyr', ru: 'Первомученик' }],
    ['Archdeacon', { it: 'Arcidiacono', es: 'Archidiácono', fr: 'Archidiacre', de: 'Erzdiakon', pt: 'Arquidiácono', ro: 'Arhidiacon', la: 'Archidiaconus', ru: 'Архидиакон' }],
    ['Archbishop', { it: 'Arcivescovo', es: 'Arzobispo', fr: 'Archevêque', de: 'Erzbischof', pt: 'Arcebispo', ro: 'Arhiepiscop', la: 'Archiepiscopus', ru: 'Архиепископ' }],
    ['Metropolitan', { it: 'Metropolita', es: 'Metropolita', fr: 'Métropolite', de: 'Metropolit', pt: 'Metropolita', ro: 'Mitropolit', la: 'Metropolita', ru: 'Митрополит' }],
    ['Patriarch', { it: 'Patriarca', es: 'Patriarca', fr: 'Patriarche', de: 'Patriarch', pt: 'Patriarca', ro: 'Patriarh', la: 'Patriarcha', ru: 'Патриарх' }],
    ['Stylite', { it: 'Stilita', es: 'Estilita', fr: 'Stylite', de: 'Stylit', pt: 'Estilita', ro: 'Stâlpnic', la: 'Stylita', ru: 'Столпник' }],
    ['Venerable', { it: 'Venerabile', es: 'Venerable', fr: 'Vénérable', de: 'Ehrwürdiger', pt: 'Venerável', ro: 'Cuvios', la: 'Venerabilis', ru: 'Преподобный' }],
    ['Apostle and Evangelist', { it: 'Apostolo ed Evangelista', es: 'Apóstol y Evangelista', fr: 'Apôtre et Évangéliste', de: 'Apostel und Evangelist', pt: 'Apóstolo e Evangelista', ro: 'Apostol și Evanghelist', la: 'Apostolus et Evangelista', ru: 'Апостол и Евангелист' }],
    ['Doctor of the Church', { it: 'Dottore della Chiesa', es: 'Doctor de la Iglesia', fr: "Docteur de l'Église", de: 'Kirchenlehrer', pt: 'Doutor da Igreja', ro: 'Învățător al Bisericii', la: 'Ecclesiae Doctor', ru: 'Учитель Церкви' }],
    ['Bishop and Martyr', { it: 'Vescovo e Martire', es: 'Obispo y Mártir', fr: 'Évêque et Martyr', de: 'Bischof und Märtyrer', pt: 'Bispo e Mártir', ro: 'Episcop și Mucenic', la: 'Episcopus et Martyr', ru: 'Епископ и Священномученик' }],
    ['Bishop & Martyr', { it: 'Vescovo e Martire', es: 'Obispo y Mártir', fr: 'Évêque et Martyr', de: 'Bischof und Märtyrer', pt: 'Bispo e Mártir', ro: 'Episcop și Mucenic', la: 'Episcopus et Martyr', ru: 'Епископ и Священномученик' }],
    ['Virgin and Martyr', { it: 'Vergine e Martire', es: 'Virgen y Mártir', fr: 'Vierge et Martyre', de: 'Jungfrau und Märtyrerin', pt: 'Virgem e Mártir', ro: 'Fecioară și Muceniță', la: 'Virgo et Martyr', ru: 'Дева и Мученица' }],
    ['Virgin & Martyr', { it: 'Vergine e Martire', es: 'Virgen y Mártir', fr: 'Vierge et Martyre', de: 'Jungfrau und Märtyrerin', pt: 'Virgem e Mártir', ro: 'Fecioară și Muceniță', la: 'Virgo et Martyr', ru: 'Дева и Мученица' }],
    ['Pope and Martyr', { it: 'Papa e Martire', es: 'Papa y Mártir', fr: 'Pape et Martyr', de: 'Papst und Märtyrer', pt: 'Papa e Mártir', ro: 'Papă și Mucenic', la: 'Papa et Martyr', ru: 'Папа и Священномученик' }],
    ['Deacon and Martyr', { it: 'Diacono e Martire', es: 'Diácono e Mártir', fr: 'Diacre et Martyr', de: 'Diakon und Märtyrer', pt: 'Diácono e Mártir', ro: 'Diacon și Mucenic', la: 'Diaconus et Martyr', ru: 'Диакон и Мученик' }],
    ['Father of the Church', { it: 'Padre della Chiesa', es: 'Padre de la Iglesia', fr: "Père de l'Église", de: 'Kirchenvater', pt: 'Padre da Igreja', ro: 'Părinte al Bisericii', la: 'Pater Ecclesiae', ru: 'Отец Церкви' }],
    ['Apostle to the Nations', { it: 'Apostolo delle Genti', es: 'Apóstol de las Gentes', fr: 'Apôtre des Nations', de: 'Apostel der Völker', pt: 'Apóstolo das Nações', ro: 'Apostolul Neamurilor', la: 'Apostolus Gentium', ru: 'Апостол Язычников' }],
    ['Apostle', { it: 'Apostolo', es: 'Apóstol', fr: 'Apôtre', de: 'Apostel', pt: 'Apóstolo', ro: 'Apostol', la: 'Apostolus', ru: 'Апостол' }],
    ['Martyr', { it: 'Martire', es: 'Mártir', fr: 'Martyr', de: 'Märtyrer', pt: 'Mártir', ro: 'Mucenic', la: 'Martyr', ru: 'Мученик' }],
    ['Martyrs', { it: 'Martiri', es: 'Mártires', fr: 'Martyrs', de: 'Märtyrer', pt: 'Mártires', ro: 'Mucenici', la: 'Martyres', ru: 'Мученики' }],
    ['Bishop', { it: 'Vescovo', es: 'Obispo', fr: 'Évêque', de: 'Bischof', pt: 'Bispo', ro: 'Episcop', la: 'Episcopus', ru: 'Епископ' }],
    ['Pope', { it: 'Papa', es: 'Papa', fr: 'Pape', de: 'Papst', pt: 'Papa', ro: 'Papă', la: 'Papa', ru: 'Папа' }],
    ['Abbot', { it: 'Abate', es: 'Abad', fr: 'Abbé', de: 'Abt', pt: 'Abade', ro: 'Egumen', la: 'Abbas', ru: 'Игумен' }],
    ['Priest', { it: 'Sacerdote', es: 'Sacerdote', fr: 'Prêtre', de: 'Priester', pt: 'Sacerdote', ro: 'Preot', la: 'Presbyter', ru: 'Священник' }],
    ['Virgin', { it: 'Vergine', es: 'Virgen', fr: 'Vierge', de: 'Jungfrau', pt: 'Virgem', ro: 'Fecioară', la: 'Virgo', ru: 'Дева' }]
  ];

  for (const [eng, dict] of tokens) {
    if (trans.includes(eng)) {
      const repl = dict[lang] || dict.it || eng;
      trans = trans.replace(eng, repl);
    }
  }

  return trans;
}

export function getLiturgicalBioFallback(name, title, lang = 'it') {
  return BIO_FALLBACKS[lang] || BIO_FALLBACKS.it || BIO_FALLBACKS.en;
}

export function getLiturgicalQuoteFallback(color = 'white', lang = 'it') {
  const cKey = (color === 'red' || color === 'blue') ? color : 'white';
  const group = QUOTE_FALLBACKS[cKey] || QUOTE_FALLBACKS.white;
  return group[lang] || group.it || group.en;
}

export function getLocalizedSaint(saint, lang = 'it') {
  if (!saint) return null;

  // 1. Look up in catalog
  const catalogEntry = SAINTS_I18N_CATALOG[saint.name] ||
                       (saint.name_it && SAINTS_I18N_CATALOG[saint.name_it]) ||
                       (saint.displayName && SAINTS_I18N_CATALOG[saint.displayName]);

  let name = '';
  let title = '';
  let quote = '';
  let bio = '';

  if (catalogEntry && catalogEntry[lang]) {
    const entry = catalogEntry[lang];
    name = entry.name || '';
    title = entry.title || '';
    quote = entry.quote || '';
    bio = entry.bio || '';
  }

  // 2. Name resolution
  if (!name) {
    if (saint[`name_${lang}`]) name = saint[`name_${lang}`];
    else if (lang === 'en') name = saint.name;
    else {
      name = translateSaintName(saint.name || '', lang, saint.name_it || saint.name_la || '');
    }
  }

  // 3. Title resolution
  if (!title) {
    if (saint[`title_${lang}`]) title = saint[`title_${lang}`];
    else if (lang === 'en') title = saint.title || '';
    else {
      title = translateSaintTitle(saint.title || '', lang, saint.title_it || '');
    }
  }

  // 4. Quote resolution
  if (!quote) {
    if (saint[`quote_${lang}`]) quote = saint[`quote_${lang}`];
    else if (lang === 'en') quote = saint.quote || saint.quote_en || '';
    else {
      quote = getLiturgicalQuoteFallback(saint.color || 'white', lang);
    }
  }

  // 5. Bio resolution
  if (!bio) {
    if (saint[`bio_${lang}`]) bio = saint[`bio_${lang}`];
    else if (lang === 'en') bio = saint.bio || '';
    else {
      bio = getLiturgicalBioFallback(name, title, lang);
    }
  }

  // 6. Scripture reference
  const scriptureRef = localizeScriptureRef(saint.scriptureRef, lang);

  // 7. Liturgical color and rank localization
  const colorName = getLocalizedColorName(saint.color || 'white', lang);
  const rankName = getLocalizedRankName(saint.rank || 'memorial', lang);

  // 8. Nationality meta resolution (always re-localized in current lang)
  const natCode = saint.nationality || saint.nationalityMeta?.code || 'universal';
  const nationalityMeta = getNationalityMeta(natCode, lang);

  return {
    ...saint,
    displayName: name,
    displayTitle: title,
    displayQuote: quote,
    displayBio: bio,
    displayScriptureRef: scriptureRef,
    colorName,
    rankName,
    nationalityMeta,
    // Convenience aliases
    name,
    title,
    quote,
    bio,
    scriptureRef
  };
}

