export function getSaintsForConfession(confession = 'ecumenical') {
  return SAINTS_DATA[confession] || SAINTS_DATA.ecumenical;
}

function getCalendarForFaith(calendar, faith) {
  return Object.fromEntries(
    Object.entries(calendar)
      .map(([date, saints]) => [date, saints.filter(saint => matchesTradition(saint, faith))])
      .filter(([, saints]) => saints.length > 0)
  );
}

function getNationalCalendarsForFaith(calendars, faith) {
  return Object.fromEntries(
    Object.entries(calendars)
      .map(([nationality, calendar]) => [nationality, getCalendarForFaith(calendar, faith)])
      .filter(([, calendar]) => Object.keys(calendar).length > 0)
  );
}

export function renderLiturgicalLegendHtml(confession = 'ecumenical', userNationality = 'universal', lang = 'it', compact = false) {
  const normConf = (confession || 'ecumenical').toLowerCase();
  const normNat = (userNationality || 'universal').toLowerCase();

  const isRomanian = normNat === 'ro' || (normConf === 'orthodox' && normNat === 'ro');
  const isGreek = normNat === 'gr' || (normConf === 'orthodox' && normNat === 'gr');
  const isSlavic = ['ru', 'rs', 'ge'].includes(normNat) || (normConf === 'orthodox' && ['ru', 'rs', 'ge'].includes(normNat));

  const l = (obj) => (obj && (obj[lang] || obj.it || obj.en)) || '';

  // 1. Romanian Orthodox (BOR) System
  if (isRomanian) {
    const title = l(LEGEND_I18N.romanian_title);
    const redLabel = CROSS_LABELS_I18N.red_cross[lang] || CROSS_LABELS_I18N.red_cross.en;
    const blueLabel = CROSS_LABELS_I18N.blue_cross[lang] || CROSS_LABELS_I18N.blue_cross.en;
    const blackLabel = CROSS_LABELS_I18N.black_cross[lang] || CROSS_LABELS_I18N.black_cross.en;
    const noneLabel = CROSS_LABELS_I18N.no_cross[lang] || CROSS_LABELS_I18N.no_cross.en;

    const redDesc = l(LEGEND_I18N.romanian_red_desc);
    const blueDesc = l(LEGEND_I18N.romanian_blue_desc);
    const blackDesc = l(LEGEND_I18N.romanian_black_desc);
    const noneDesc = l(LEGEND_I18N.romanian_none_desc);

    if (compact) {
      return `
        <div class="hidden xl:flex items-center gap-2.5 text-[11px] font-sans text-[var(--text-muted)] border-l border-stone-300 dark:border-stone-700 pl-3">
          <span class="flex items-center gap-1 font-semibold text-red-600 dark:text-red-400" title="${redDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-red-600 ring-1 ring-red-400"></span>
            <span>† ${redLabel}</span>
          </span>
          <span class="flex items-center gap-1 font-semibold text-blue-600 dark:text-blue-400" title="${blueDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-blue-600 ring-1 ring-blue-400"></span>
            <span>† ${blueLabel}</span>
          </span>
          <span class="flex items-center gap-1 font-semibold text-stone-900 dark:text-stone-200 liturgical-cross-black-text" title="${blackDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-stone-800 dark:bg-stone-300 ring-1 ring-stone-600 liturgical-cross-black-dot"></span>
            <span>† ${blackLabel}</span>
          </span>
          <span class="flex items-center gap-1 text-stone-600 dark:text-stone-400" title="${noneDesc}">
            <span>${noneLabel}</span>
          </span>
        </div>
      `;
    }

    return `
      <div class="bg-[var(--bg-secondary)] border border-stone-200 dark:border-stone-800/80 rounded-xl p-3 flex flex-wrap items-center justify-between gap-3 text-xs">
        <div class="flex items-center gap-2">
          <span class="font-bold text-[var(--text-primary)]">${title}</span>
        </div>
        <div class="flex flex-wrap items-center gap-3 text-[11px] font-sans">
          <span class="flex items-center gap-1.5 font-bold text-red-600 dark:text-red-400" title="${redDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-red-600 dark:bg-red-500 ring-1 ring-red-400"></span>
            <span>† ${redLabel}</span>
          </span>
          <span class="flex items-center gap-1.5 font-semibold text-blue-600 dark:text-blue-400" title="${blueDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-blue-600 dark:bg-blue-500 ring-1 ring-blue-400"></span>
            <span>† ${blueLabel}</span>
          </span>
          <span class="flex items-center gap-1.5 font-semibold text-stone-900 dark:text-stone-200 liturgical-cross-black-text" title="${blackDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-stone-800 dark:bg-stone-300 ring-1 ring-stone-600 dark:ring-stone-400 liturgical-cross-black-dot"></span>
            <span>† ${blackLabel}</span>
          </span>
          <span class="flex items-center gap-1.5 font-normal text-stone-600 dark:text-stone-400" title="${noneDesc}">
            <span>${noneLabel}</span>
          </span>
        </div>
      </div>
    `;
  }

  // 2. Greek Orthodox Typikon
  if (isGreek) {
    const title = l(LEGEND_I18N.greek_title);
    const redLabel = (lang === 'el' || lang === 'gr') ? 'Κόκκινος Σταυρός' : (CROSS_LABELS_I18N.red_cross[lang] || CROSS_LABELS_I18N.red_cross.en);
    const blackLabel = (lang === 'el' || lang === 'gr') ? 'Μαύρος Σταυρός' : (CROSS_LABELS_I18N.black_cross[lang] || CROSS_LABELS_I18N.black_cross.en);
    const noneLabel = (lang === 'el' || lang === 'gr') ? 'Χωρίς σταυρό' : (CROSS_LABELS_I18N.no_cross[lang] || CROSS_LABELS_I18N.no_cross.en);
    const redDesc = l(LEGEND_I18N.greek_red_desc);
    const blackDesc = l(LEGEND_I18N.greek_black_desc);
    const noneDesc = l(LEGEND_I18N.romanian_none_desc);

    if (compact) {
      return `
        <div class="hidden xl:flex items-center gap-2.5 text-[11px] font-sans text-[var(--text-muted)] border-l border-stone-300 dark:border-stone-700 pl-3">
          <span class="flex items-center gap-1 font-semibold text-red-600 dark:text-red-400" title="${redDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-red-600 ring-1 ring-red-400"></span>
            <span>† ${redLabel}</span>
          </span>
          <span class="flex items-center gap-1 font-semibold text-stone-900 dark:text-stone-200 liturgical-cross-black-text" title="${blackDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-stone-800 dark:bg-stone-300 ring-1 ring-stone-600 liturgical-cross-black-dot"></span>
            <span>† ${blackLabel}</span>
          </span>
          <span class="flex items-center gap-1 text-stone-600 dark:text-stone-400" title="${noneDesc}">
            <span>${noneLabel}</span>
          </span>
        </div>
      `;
    }

    return `
      <div class="bg-[var(--bg-secondary)] border border-stone-200 dark:border-stone-800/80 rounded-xl p-3 flex flex-wrap items-center justify-between gap-3 text-xs">
        <div class="flex items-center gap-2">
          <span class="font-bold text-[var(--text-primary)]">${title}</span>
        </div>
        <div class="flex flex-wrap items-center gap-3 text-[11px] font-sans">
          <span class="flex items-center gap-1.5 font-bold text-red-600 dark:text-red-400" title="${redDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-red-600 dark:bg-red-500 ring-1 ring-red-400"></span>
            <span>† ${redLabel}</span>
          </span>
          <span class="flex items-center gap-1.5 font-semibold text-stone-900 dark:text-stone-200 liturgical-cross-black-text" title="${blackDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-stone-800 dark:bg-stone-300 ring-1 ring-stone-600 dark:ring-stone-400 liturgical-cross-black-dot"></span>
            <span>† ${blackLabel}</span>
          </span>
          <span class="flex items-center gap-1.5 font-normal text-stone-600 dark:text-stone-400" title="${noneDesc}">
            <span>${noneLabel}</span>
          </span>
        </div>
      </div>
    `;
  }

  // 3. Slavic Orthodox Typikon
  if (isSlavic) {
    const title = l(LEGEND_I18N.slavic_title);
    const redLabel = CROSS_LABELS_I18N.red_cross[lang] || CROSS_LABELS_I18N.red_cross.en;
    const blackLabel = CROSS_LABELS_I18N.black_cross[lang] || CROSS_LABELS_I18N.black_cross.en;
    const noneLabel = CROSS_LABELS_I18N.no_cross[lang] || CROSS_LABELS_I18N.no_cross.en;
    const redDesc = l(LEGEND_I18N.slavic_red_desc);
    const blackDesc = l(LEGEND_I18N.slavic_black_desc);
    const noneDesc = l(LEGEND_I18N.romanian_none_desc);

    if (compact) {
      return `
        <div class="hidden xl:flex items-center gap-2.5 text-[11px] font-sans text-[var(--text-muted)] border-l border-stone-300 dark:border-stone-700 pl-3">
          <span class="flex items-center gap-1 font-semibold text-red-600 dark:text-red-400" title="${redDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-red-600 ring-1 ring-red-400"></span>
            <span>† ${redLabel}</span>
          </span>
          <span class="flex items-center gap-1 font-semibold text-stone-900 dark:text-stone-200 liturgical-cross-black-text" title="${blackDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-stone-800 dark:bg-stone-300 ring-1 ring-stone-600 liturgical-cross-black-dot"></span>
            <span>† ${blackLabel}</span>
          </span>
          <span class="flex items-center gap-1 text-stone-600 dark:text-stone-400" title="${noneDesc}">
            <span>${noneLabel}</span>
          </span>
        </div>
      `;
    }

    return `
      <div class="bg-[var(--bg-secondary)] border border-stone-200 dark:border-stone-800/80 rounded-xl p-3 flex flex-wrap items-center justify-between gap-3 text-xs">
        <div class="flex items-center gap-2">
          <span class="font-bold text-[var(--text-primary)]">${title}</span>
        </div>
        <div class="flex flex-wrap items-center gap-3 text-[11px] font-sans">
          <span class="flex items-center gap-1.5 font-bold text-red-600 dark:text-red-400" title="${redDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-red-600 dark:bg-red-500 ring-1 ring-red-400"></span>
            <span>† ${redLabel}</span>
          </span>
          <span class="flex items-center gap-1.5 font-semibold text-stone-900 dark:text-stone-200 liturgical-cross-black-text" title="${blackDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-stone-800 dark:bg-stone-300 ring-1 ring-stone-600 dark:ring-stone-400 liturgical-cross-black-dot"></span>
            <span>† ${blackLabel}</span>
          </span>
          <span class="flex items-center gap-1.5 font-normal text-stone-600 dark:text-stone-400" title="${noneDesc}">
            <span>${noneLabel}</span>
          </span>
        </div>
      </div>
    `;
  }

  // 4. Roman Catholic / General Roman Calendar / CEI
  // STRICT RULE: No crosses. Pure liturgical vestment colors.
  const isSpanish = normNat === 'es' || normNat === 'pt';
  const catholicTitle = l(LEGEND_I18N.catholic_title);

  const whiteName = LITURGICAL_COLORS.white[`name_${lang}`] || LITURGICAL_COLORS.white.name_it || LITURGICAL_COLORS.white.name;
  const redName = LITURGICAL_COLORS.red[`name_${lang}`] || LITURGICAL_COLORS.red.name_it || LITURGICAL_COLORS.red.name;
  const greenName = LITURGICAL_COLORS.green[`name_${lang}`] || LITURGICAL_COLORS.green.name_it || LITURGICAL_COLORS.green.name;
  const violetName = LITURGICAL_COLORS.violet[`name_${lang}`] || LITURGICAL_COLORS.violet.name_it || LITURGICAL_COLORS.violet.name;
  const roseName = LITURGICAL_COLORS.rose[`name_${lang}`] || LITURGICAL_COLORS.rose.name_it || LITURGICAL_COLORS.rose.name;
  const blueName = LITURGICAL_COLORS.blue[`name_${lang}`] || LITURGICAL_COLORS.blue.name_it || LITURGICAL_COLORS.blue.name;

  const whiteDesc = l(LEGEND_I18N.catholic_white_desc);
  const redDesc = l(LEGEND_I18N.catholic_red_desc);
  const greenDesc = l(LEGEND_I18N.catholic_green_desc);
  const violetDesc = l(LEGEND_I18N.catholic_violet_desc);
  const roseDesc = l(LEGEND_I18N.catholic_rose_desc);
  const blueDesc = l(LEGEND_I18N.catholic_blue_desc);

  if (compact) {
    return `
      <div class="hidden xl:flex items-center gap-2.5 text-[11px] font-sans text-[var(--text-muted)] border-l border-stone-300 dark:border-stone-700 pl-3">
        <span class="flex items-center gap-1 font-semibold text-amber-700 dark:text-amber-300" title="${whiteDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-amber-400 ring-1 ring-amber-500"></span>
          <span>${whiteName}</span>
        </span>
        <span class="flex items-center gap-1 font-semibold text-red-600 dark:text-red-400" title="${redDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-red-600 ring-1 ring-red-400"></span>
          <span>${redName}</span>
        </span>
        <span class="flex items-center gap-1 text-emerald-700 dark:text-emerald-400 font-semibold" title="${greenDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-emerald-600"></span>
          <span>${greenName}</span>
        </span>
        <span class="flex items-center gap-1 text-purple-700 dark:text-purple-300 font-semibold" title="${violetDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-purple-600"></span>
          <span>${violetName}</span>
        </span>
        <span class="flex items-center gap-1 text-rose-600 dark:text-rose-400 font-semibold" title="${roseDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-rose-500"></span>
          <span>${roseName}</span>
        </span>
        ${isSpanish ? `
          <span class="flex items-center gap-1 text-blue-600 dark:text-blue-400 font-semibold" title="${blueDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-blue-600"></span>
            <span>${blueName}</span>
          </span>
        ` : ''}
      </div>
    `;
  }

  return `
    <div class="bg-[var(--bg-secondary)] border border-stone-200 dark:border-stone-800/80 rounded-xl p-3 flex flex-wrap items-center justify-between gap-3 text-xs">
      <div class="flex items-center gap-2">
        <span class="font-bold text-[var(--text-primary)]">${catholicTitle}</span>
      </div>
      <div class="flex flex-wrap items-center gap-3 text-[11px] font-sans">
        <span class="flex items-center gap-1.5 font-semibold text-amber-700 dark:text-amber-300" title="${whiteDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-amber-400 ring-1 ring-amber-500"></span>
          <span>${whiteName}</span>
        </span>
        <span class="flex items-center gap-1.5 font-semibold text-red-600 dark:text-red-400" title="${redDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-red-600 ring-1 ring-red-400"></span>
          <span>${redName}</span>
        </span>
        <span class="flex items-center gap-1.5 font-semibold text-emerald-700 dark:text-emerald-400" title="${greenDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-emerald-600"></span>
          <span>${greenName}</span>
        </span>
        <span class="flex items-center gap-1.5 font-semibold text-purple-700 dark:text-purple-300" title="${violetDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-purple-600"></span>
          <span>${violetName}</span>
        </span>
        <span class="flex items-center gap-1.5 font-semibold text-rose-600 dark:text-rose-400" title="${roseDesc}">
          <span class="w-2.5 h-2.5 rounded-full bg-rose-500"></span>
          <span>${roseName}</span>
        </span>
        ${isSpanish ? `
          <span class="flex items-center gap-1.5 font-semibold text-blue-600 dark:text-blue-400" title="${blueDesc}">
            <span class="w-2.5 h-2.5 rounded-full bg-blue-600"></span>
            <span>${blueName}</span>
          </span>
        ` : ''}
      </div>
    </div>
  `;
}

export const SAINTS_BY_FAITH = Object.fromEntries(
  ['catholic', 'traditional', 'orthodox', 'protestant', 'ecumenical'].map(faith => [
    faith,
    {
      curated: SAINTS_DATA[faith] || [],
      fallback: TRADITION_FALLBACK_PATRONS[faith] || [],
      dailyCalendar: getCalendarForFaith(DAILY_SAINTS_CALENDAR, faith),
      nationalCalendars: getNationalCalendarsForFaith(NATIONAL_SAINTS_BY_DATE, faith),
      orthodoxCalendar: faith === 'orthodox' ? ORTHODOX_SAINTS_CALENDAR : {}
    }
  ])
);
